import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Fase } from '../types'
import { limparMensagem, montarPrompt, SISTEMA, tituloDe, trocarTitulo } from './lib'

type $ = EngineInterface

const PAINEL = 'commit-ia'

// O estado mora no host: escrever num atom redesenha o painel.
const fase = atom({ plugin: 'commit-ia', key: 'fase' } as const, 'vazio' as Fase)
const mensagem = atom({ plugin: 'commit-ia', key: 'mensagem' } as const, '')
const arquivos = atom({ plugin: 'commit-ia', key: 'arquivos' } as const, [] as string[])
const aviso = atom({ plugin: 'commit-ia', key: 'aviso' } as const, '')

let idioma = 'pt-BR'

async function git($: $, args: string[], stdin?: string) {
  return $.process.run(['git', ...args], { stdin, timeoutMs: 30_000 })
}

async function mostrar($: $, f: Fase, texto = ''): Promise<void> {
  await update($, fase, () => f)
  await update($, aviso, () => texto)
}

/** Pede a mensagem ao Haiku: uma chamada avulsa, fora da conversa do agente. */
async function gerar($: $): Promise<void> {
  await mostrar($, 'gerando', 'O Haiku está lendo o diff…')
  const diff = await git($, ['diff', '--staged'])
  const historico = await git($, ['log', '-10', '--pretty=%s'])
  const resposta = await $.model.complete({
    model: 'haiku',
    effort: 'low',
    maxTokens: 400,
    timeoutMs: 30_000,
    system: SISTEMA,
    prompt: montarPrompt({
      diff: diff.stdout,
      arquivos: await read($, arquivos),
      historico: historico.stdout.split('\n').filter(Boolean),
      idioma,
    }),
  })
  if (!resposta.isAnswered) return mostrar($, 'erro', `O modelo não respondeu (${resposta.reason}). Tente "Gerar outra".`)

  await update($, mensagem, () => limparMensagem(resposta.text))
  await mostrar($, 'pronto')
}

/** Lê o que está staged; sem nada staged, mostra o status e oferece o git add -A. */
async function carregar($: $): Promise<void> {
  const staged = await git($, ['diff', '--staged', '--name-only'])
  const lista = staged.stdout.split('\n').filter(Boolean)
  if (lista.length > 0) {
    await update($, arquivos, () => lista)
    return gerar($)
  }
  const status = await git($, ['status', '--short'])
  await update($, arquivos, () => status.stdout.split('\n').filter(Boolean))
  await update($, mensagem, () => '')
  await mostrar($, 'vazio', status.stdout.trim() === '' ? 'Nada para commitar: a árvore está limpa.' : 'Nada staged ainda.')
}

async function commitar($: $): Promise<void> {
  if ((await read($, mensagem)).trim() === '') return mostrar($, 'erro', 'Ainda não há mensagem para commitar.')
  await mostrar($, 'commitando', 'Rodando git commit…')
  // A mensagem vai pelo stdin (-F -): nada de escapar aspas no shell.
  const feito = await git($, ['commit', '-F', '-'], `${await read($, mensagem)}\n`)
  if (feito.exitCode !== 0) {
    const erro = (feito.stderr || feito.stdout).trim().split('\n').slice(-4).join('\n')
    return mostrar($, 'erro', `O commit falhou:\n${erro}`)
  }
  const hash = (await git($, ['rev-parse', '--short', 'HEAD'])).stdout.trim()
  $.ui.toast(`✅ Commit ${hash}: ${tituloDe(await read($, mensagem))}`)
  await mostrar($, 'vazio')
  await $.ui.close({ id: PAINEL })
}

export const register: Register = (on, options) => {
  idioma = String(options.idioma ?? 'pt-BR')

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'commit', description: 'commit-ia: o Haiku escreve a mensagem do commit; você revisa e commita' })

    return next(e)
  })

  on('command.run', { command: 'commit' }, async $ => {
    await $.ui.open({ id: PAINEL, title: 'Commit com IA', focus: true, closeOnEscape: true })
    void carregar($)

    return { text: 'Painel do commit aberto.' }
  })

  on('ui.render', { component: 'Pane', requestId: PAINEL }, async ($, e) => {
    if (e.surface === 'mobile') {
      const { Text } = $.ui.resolve(e)
      return <Text>Abra o /commit no terminal.</Text>
    }
    const { Box, Button, Input, Text } = $.ui.resolve(e)
    const f = await read($, fase)
    const msg = await read($, mensagem)
    const lista = await read($, arquivos)
    const nota = await read($, aviso)

    const fechar = <Button key="cancelar" label="Cancelar" role="dismiss" onPress={() => void $.ui.close({ id: PAINEL })} />

    if (f === 'vazio') {
      return (
        <Box flexDirection="column" gap={1}>
          <Text>{nota}</Text>
          {lista.map(linha => <Text dimColor>{linha}</Text>)}
          <Box gap={2}>
            {lista.length > 0 && (
              <Button
                key="add"
                label="Adicionar tudo (git add -A)"
                variant="primary"
                onPress={async () => {
                  await git($, ['add', '-A'])
                  await carregar($)
                }}
              />
            )}
            {fechar}
          </Box>
        </Box>
      )
    }

    return (
      <Box flexDirection="column" gap={1}>
        {f === 'editando' ? (
          <Input
            key="titulo"
            label="Título: "
            value={tituloDe(msg)}
            submitLabel="salvar"
            autoFocus
            onSubmit={async titulo => {
              await update($, mensagem, m => trocarTitulo(m, titulo))
              await mostrar($, 'pronto')
            }}
          />
        ) : (
          <Box flexDirection="column" borderStyle="round" paddingX={1}>
            <Text dimColor={f === 'gerando'}>{msg === '' ? '…' : msg}</Text>
          </Box>
        )}
        <Text dimColor>
          {lista.length} arquivo(s): {lista.join(', ')}
        </Text>
        {nota !== '' && <Text color={f === 'erro' ? 'red' : undefined}>{nota}</Text>}
        <Box gap={2}>
          <Button key="commitar" label="Commitar" variant="primary" onPress={() => commitar($)} />
          <Button key="outra" label="Gerar outra" onPress={() => gerar($)} />
          <Button key="editar" label="Editar" onPress={() => mostrar($, 'editando')} />
          {fechar}
        </Box>
      </Box>
    )
  })
}

