// Lógica pura do commit-ia: montar o pedido ao modelo e limpar a resposta.

/** Diff grande custa caro e confunde o modelo: acima disso, só o começo vai. */
export const LIMITE_DIFF = 12_000

export function truncarDiff(diff: string, limite = LIMITE_DIFF): string {
  if (diff.length <= limite) return diff

  return `${diff.slice(0, limite)}\n\n[diff cortado: ${diff.length - limite} caracteres a mais não foram enviados]`
}

export const SISTEMA =
  'Você escreve mensagens de commit no padrão Conventional Commits. Responda só com a mensagem, sem comentários, sem cercas de código.'

export function montarPrompt(entrada: { diff: string; arquivos: string[]; historico: string[]; idioma: string }): string {
  return [
    `Escreva a mensagem de commit para as mudanças abaixo, em ${entrada.idioma}.`,
    'Formato: título `tipo(escopo): resumo` com até 72 caracteres; uma linha em branco; e, se ajudar, até 4 linhas de corpo dizendo o porquê.',
    'Não inclua trailers (Co-Authored-By, Signed-off-by) nem menção a IA.',
    '',
    'Siga o estilo dos últimos commits do repositório:',
    ...entrada.historico.map(linha => `- ${linha}`),
    '',
    `Arquivos: ${entrada.arquivos.join(', ')}`,
    '',
    '```diff',
    truncarDiff(entrada.diff),
    '```',
  ].join('\n')
}

// Atribuição a IA nunca entra no commit, mesmo que o modelo escreva.
const ATRIBUICAO = /^\s*(co-authored-by:.*|.*generated (with|by) .*(claude|ai\b|ia\b).*|🤖.*)$/i

/** Tira cercas ```, aspas em volta e linhas de atribuição da resposta do modelo. */
export function limparMensagem(resposta: string): string {
  const semCerca = resposta.trim().replace(/^```[\w-]*\n?/, '').replace(/\n?```$/, '')
  const semAspas = semCerca.trim().replace(/^(["'`])([\s\S]*)\1$/, '$2')
  const linhas = semAspas.split('\n').filter(linha => !ATRIBUICAO.test(linha))

  return linhas.join('\n').replace(/\n{3,}/g, '\n\n').trim()
}

/** Troca só o título (primeira linha), mantendo o corpo. */
export function trocarTitulo(mensagem: string, titulo: string): string {
  const [, ...corpo] = mensagem.split('\n')

  return [titulo.trim(), ...corpo].join('\n')
}

export function tituloDe(mensagem: string): string {
  return mensagem.split('\n')[0] ?? ''
}

