/** Em que ponto o painel está. */
export type Fase = 'vazio' | 'gerando' | 'pronto' | 'editando' | 'commitando' | 'erro'

declare module 'claude-code' {
  interface PluginState {
    'commit-ia': {
      fase: Fase
      /** A mensagem proposta (título na primeira linha). */
      mensagem: string
      /** Arquivos staged, ou o `git status --short` quando não há nada staged. */
      arquivos: string[]
      /** Erro ou observação mostrada no painel. */
      aviso: string
    }
  }
}
